-- OFFLINE fixture only: no production migration. Original Stage27 definitions unchanged.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_managed_image') IS NULL OR to_regnamespace('design_managed_derived') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_derived_storage_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_derived_verifier_authorizer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_derived_verifier LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_derived_storage_issuer,design_derived_verifier_authorizer,design_derived_verifier;
CREATE SCHEMA design_managed_derived AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_managed_derived FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_managed_derived TO design_identity_runtime,design_derived_storage_issuer,design_derived_verifier_authorizer,design_derived_verifier,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_managed_derived TO design_managed_image_capability;
CREATE TABLE design_managed_derived.permissions(id text PRIMARY KEY,authority jsonb NOT NULL,intent jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX derived_permission_response ON design_managed_derived.permissions ((intent->'response'));
CREATE TABLE design_managed_derived.put_claims(response_digest text PRIMARY KEY,permission_id text NOT NULL REFERENCES design_managed_derived.permissions,intent jsonb NOT NULL);
CREATE TABLE design_managed_derived.objects(response_digest text PRIMARY KEY REFERENCES design_managed_derived.put_claims,receipt jsonb NOT NULL);
CREATE TABLE design_managed_derived.tasks(id text PRIMARY KEY,authority jsonb NOT NULL,response_digest text NOT NULL REFERENCES design_managed_derived.objects,object_digest text NOT NULL,verifier jsonb NOT NULL,policy_version text NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_managed_derived.reports(task_id text PRIMARY KEY REFERENCES design_managed_derived.tasks,report jsonb NOT NULL,active boolean NOT NULL DEFAULT true);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['permissions','put_claims','objects','tasks','reports'] LOOP EXECUTE format('ALTER TABLE design_managed_derived.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_managed_derived.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY capability_only ON design_managed_derived.%I TO design_managed_image_capability USING(true) WITH CHECK(true)',t);EXECUTE format('GRANT SELECT,INSERT ON design_managed_derived.%I TO design_managed_image_capability',t);EXECUTE format('CREATE TRIGGER derived_immutable BEFORE UPDATE OR DELETE ON design_managed_derived.%I FOR EACH ROW EXECUTE FUNCTION design_managed_image.immutable_row()',t);END LOOP;END$$;
GRANT UPDATE(active) ON design_managed_derived.permissions,design_managed_derived.tasks,design_managed_derived.reports TO design_managed_image_capability;
CREATE FUNCTION design_managed_derived.issuer_auth(token text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN
 IF (session_user NOT IN ('design_derived_storage_issuer','design_derived_verifier_authorizer','design_derived_verifier') OR token IS NULL OR length(token) NOT BETWEEN 32 AND 200 OR token~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(token,'UTF8')),'hex'),scope);
 IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN r->'authority';END$$;
-- Reuses original immutable persisted response, but checks EVERY live source and receipt
-- for either separately authenticated issuer or runtime. No relaxation of old auth().
CREATE FUNCTION design_managed_derived.check_response(a jsonb,r jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE old jsonb;s design_managed_image.sources;cl design_managed_image.claims;p design_managed_image.receipts;c design_managed_image.receipts;BEGIN
 IF (NOT design_managed_image.exact(r,ARRAY['schemaVersion','sourceRecordDigest','descriptor']) OR r->>'schemaVersion'<>'design-managed-image-response-v1' OR jsonb_typeof(r->'sourceRecordDigest') IS DISTINCT FROM 'string') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 SELECT record INTO STRICT old FROM design_managed_image.responses WHERE source_digest=r->>'sourceRecordDigest' AND request_id=r->'descriptor'->>'requestId';
 IF (old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT s FROM design_managed_image.sources WHERE digest=r->>'sourceRecordDigest' AND active FOR SHARE;PERFORM design_managed_image.check_source(s.record,a);
 SELECT * INTO STRICT cl FROM design_managed_image.claims WHERE owner_key=design_managed_image.owner_key(a) AND request_id=r->'descriptor'->>'requestId';
 PERFORM design_managed_image.check_intent(cl.intent,a);
 IF (cl.intent->'source' IS DISTINCT FROM design_managed_image.transform_source(a,s.record->>'mediaId')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 p:=design_managed_image.receipt(a,'processing',cl.request_id,cl.intent);c:=design_managed_image.receipt(a,'cost',cl.request_id,cl.intent);
 IF (cl.processing_id IS DISTINCT FROM p.id OR cl.cost_id IS DISTINCT FROM c.id OR p.expires_at<=clock_timestamp() OR c.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN design_dependency_authority.digest(r);END$$;
CREATE FUNCTION design_managed_derived.check_put(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE rd text;s jsonb;t jsonb;b jsonb;BEGIN
 IF (NOT design_managed_image.exact(i,ARRAY['schemaVersion','response','target','cost']) OR i->>'schemaVersion'<>'design-managed-derived-put-intent-v1') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 rd:=design_managed_derived.check_response(a,i->'response');IF (((i->'response'->'descriptor'->'derivative'->>'byteLength')::bigint BETWEEN 1 AND CASE WHEN i->'response'->'descriptor'->'requestedTransform'->>'maxEdge'='1024' THEN 262144 WHEN i->'response'->'descriptor'->'requestedTransform'->>'maxEdge'='1536' THEN 524288 ELSE 0 END)) IS DISTINCT FROM true THEN RAISE EXCEPTION 'DERIVED_BUDGET_DENIED' USING ERRCODE='42501';END IF;SELECT record INTO STRICT s FROM design_managed_image.sources WHERE digest=i->'response'->>'sourceRecordDigest';t:=i->'target';b:=i->'cost';
 IF (t IS DISTINCT FROM jsonb_build_object('projectOrigin',s->'object'->'projectOrigin','bucket',s->'object'->'bucket','key','managed-derived/'||rd||'/object') OR NOT design_managed_image.exact(b,ARRAY['currency','maximumMinorUnits','maximumDispatches','commitment']) OR NOT design_managed_image.strings(b,ARRAY['currency','commitment']) OR b->>'currency'!~'^[A-Z]{3}$' OR jsonb_typeof(b->'maximumMinorUnits') IS DISTINCT FROM 'number' OR b->>'maximumMinorUnits'!~'^[1-9][0-9]*$' OR (b->>'maximumMinorUnits')::bigint NOT BETWEEN 1 AND 100000000 OR b->'maximumDispatches' IS DISTINCT FROM '1'::jsonb OR b->>'commitment'<>'one_time') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN rd;END$$;
CREATE FUNCTION design_managed_derived.permission(a jsonb,i jsonb) RETURNS design_managed_derived.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_managed_derived.permissions;BEGIN PERFORM design_managed_derived.check_put(a,i);SELECT * INTO STRICT p FROM design_managed_derived.permissions WHERE intent=i FOR SHARE;IF (NOT p.active OR p.authority IS DISTINCT FROM a OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_managed_derived.issue_put(token text,scope jsonb,id text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;rd text;BEGIN
 IF (session_user<>'design_derived_storage_issuer' OR id IS NULL OR id!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_derived.issuer_auth(token,scope);rd:=design_managed_derived.check_put(a,i);
 IF EXISTS(SELECT 1 FROM design_managed_derived.put_claims WHERE response_digest=rd) THEN RAISE EXCEPTION 'DERIVED_ALREADY_CLAIMED';END IF;
 INSERT INTO design_managed_derived.permissions VALUES(id,a,i,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_managed_derived.permission(design_managed_derived.issuer_auth(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_managed_derived.guard_put(i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_derived.permissions;cl design_managed_derived.put_claims;BEGIN a:=design_managed_image.auth();p:=design_managed_derived.permission(a,i);SELECT * INTO STRICT cl FROM design_managed_derived.put_claims WHERE response_digest=design_dependency_authority.digest(i->'response');IF (cl.intent IS DISTINCT FROM i OR cl.permission_id IS DISTINCT FROM p.id OR design_managed_image.auth() IS DISTINCT FROM a OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_derived.claim_put(i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_derived.permissions;rd text;cl design_managed_derived.put_claims;BEGIN a:=design_managed_image.auth();p:=design_managed_derived.permission(a,i);rd:=design_dependency_authority.digest(i->'response');SELECT * INTO cl FROM design_managed_derived.put_claims WHERE response_digest=rd;IF FOUND THEN IF (cl.intent IS DISTINCT FROM i OR cl.permission_id IS DISTINCT FROM p.id) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED';END IF;RETURN 'already_claimed';END IF;INSERT INTO design_managed_derived.put_claims VALUES(rd,p.id,i);PERFORM design_managed_derived.guard_put(i);RETURN 'created';END$$;
CREATE FUNCTION design_managed_derived.check_object(a jsonb,rd text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE cl design_managed_derived.put_claims;p design_managed_derived.permissions;BEGIN
 SELECT * INTO STRICT cl FROM design_managed_derived.put_claims WHERE response_digest=rd;p:=design_managed_derived.permission(a,cl.intent);
 IF (cl.permission_id IS DISTINCT FROM p.id OR NOT design_managed_image.exact(r,ARRAY['schemaVersion','responseDigest','object','derivative','private','readbackVerified']) OR r->>'schemaVersion'<>'design-managed-derived-object-v1' OR r->>'responseDigest' IS DISTINCT FROM rd OR r->'private' IS DISTINCT FROM 'true'::jsonb OR r->'readbackVerified' IS DISTINCT FROM 'true'::jsonb OR r->'derivative' IS DISTINCT FROM cl.intent->'response'->'descriptor'->'derivative' OR NOT design_managed_image.exact(r->'object',ARRAY['projectOrigin','bucket','key','version']) OR ((r->'object')-'version') IS DISTINCT FROM cl.intent->'target' OR jsonb_typeof(r->'object'->'version') IS DISTINCT FROM 'string' OR r->'object'->>'version'!~'^[A-Za-z0-9._-]{1,160}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN r;END$$;
CREATE FUNCTION design_managed_derived.publish_object(rd text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;old jsonb;BEGIN a:=design_managed_image.auth();PERFORM design_managed_derived.check_object(a,rd,r);SELECT receipt INTO old FROM design_managed_derived.objects WHERE response_digest=rd;IF FOUND THEN IF (old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_CONFLICT';END IF;ELSE INSERT INTO design_managed_derived.objects VALUES(rd,r);END IF;RETURN design_managed_derived.check_object(design_managed_image.auth(),rd,r);END$$;
CREATE FUNCTION design_managed_derived.read_object(rd text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT receipt INTO STRICT r FROM design_managed_derived.objects WHERE response_digest=rd;RETURN design_managed_derived.check_object(a,rd,r);END$$;
CREATE FUNCTION design_managed_derived.issue_task(token text,scope jsonb,id text,rd text,v jsonb,pv text,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN
 IF (session_user<>'design_derived_verifier_authorizer' OR id IS NULL OR id!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000 OR NOT design_managed_image.exact(v,ARRAY['id','version']) OR NOT design_managed_image.strings(v,ARRAY['id','version']) OR v->>'id'!~'^[A-Za-z0-9_-]{1,100}$' OR v->>'version'!~'^[A-Za-z0-9._-]{1,160}$' OR pv IS NULL OR pv!~'^[A-Za-z0-9._-]{1,160}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 a:=design_managed_derived.issuer_auth(token,scope);SELECT receipt INTO STRICT r FROM design_managed_derived.objects WHERE response_digest=rd;PERFORM design_managed_derived.check_object(a,rd,r);
 INSERT INTO design_managed_derived.tasks VALUES(id,a,rd,design_dependency_authority.digest(r),v,pv,clock_timestamp()+ttl*interval '1 millisecond',true);
 PERFORM design_managed_derived.task_context(design_managed_derived.issuer_auth(token,scope),id);RETURN true;END$$;
CREATE FUNCTION design_managed_derived.task_context(a jsonb,id text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE t design_managed_derived.tasks;o jsonb;i jsonb;s jsonb;BEGIN
 SELECT * INTO STRICT t FROM design_managed_derived.tasks WHERE tasks.id=task_context.id FOR SHARE;
 IF (NOT t.active OR t.authority IS DISTINCT FROM a OR t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 SELECT receipt INTO STRICT o FROM design_managed_derived.objects WHERE response_digest=t.response_digest;PERFORM design_managed_derived.check_object(a,t.response_digest,o);
 IF (design_dependency_authority.digest(o) IS DISTINCT FROM t.object_digest) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;
 SELECT intent INTO STRICT i FROM design_managed_derived.put_claims WHERE response_digest=t.response_digest;SELECT record INTO STRICT s FROM design_managed_image.sources WHERE digest=i->'response'->>'sourceRecordDigest';
 IF (t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('sourceRecord',s,'response',i->'response','objectReceipt',o);END$$;
CREATE FUNCTION design_managed_derived.read_task(token text,scope jsonb,id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c jsonb;BEGIN IF (session_user<>'design_derived_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_derived.issuer_auth(token,scope);c:=design_managed_derived.task_context(a,id);IF (c IS DISTINCT FROM design_managed_derived.task_context(design_managed_derived.issuer_auth(token,scope),id)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED';END IF;RETURN c;END$$;
CREATE FUNCTION design_managed_derived.guard_task(token text,scope jsonb,id text,binding jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c jsonb;t design_managed_derived.tasks;b jsonb;BEGIN
 IF (session_user<>'design_derived_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_derived.issuer_auth(token,scope);c:=design_managed_derived.task_context(a,id);SELECT * INTO STRICT t FROM design_managed_derived.tasks WHERE tasks.id=guard_task.id;
 b:=jsonb_build_object('sourceRecordDigest',design_dependency_authority.digest(c->'sourceRecord'),'responseDigest',t.response_digest,'objectReceiptDigest',t.object_digest,'requestId',c->'response'->'descriptor'->'requestId','mediaId',c->'sourceRecord'->'mediaId','sourceObjectVersion',c->'sourceRecord'->'object'->'version','derivativeObjectVersion',c->'objectReceipt'->'object'->'version','sourceSha256',c->'sourceRecord'->'source'->'sha256','derivativeSha256',c->'objectReceipt'->'derivative'->'sha256','transformDigest',design_dependency_authority.digest(c->'response'->'descriptor'->'requestedTransform'),'verifier',t.verifier,'policyVersion',t.policy_version);
 IF (binding IS DISTINCT FROM b OR design_managed_derived.issuer_auth(token,scope) IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;PERFORM design_managed_derived.task_context(a,id);RETURN true;END$$;
CREATE FUNCTION design_managed_derived.check_report(a jsonb,id text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c jsonb;t design_managed_derived.tasks;b jsonb;checks jsonb;ev jsonb;allgood boolean;anybad boolean;expected jsonb;BEGIN
 c:=design_managed_derived.task_context(a,id);SELECT * INTO STRICT t FROM design_managed_derived.tasks WHERE tasks.id=check_report.id;
 b:=jsonb_build_object('sourceRecordDigest',design_dependency_authority.digest(c->'sourceRecord'),'responseDigest',t.response_digest,'objectReceiptDigest',t.object_digest,'requestId',c->'response'->'descriptor'->'requestId','mediaId',c->'sourceRecord'->'mediaId','sourceObjectVersion',c->'sourceRecord'->'object'->'version','derivativeObjectVersion',c->'objectReceipt'->'object'->'version','sourceSha256',c->'sourceRecord'->'source'->'sha256','derivativeSha256',c->'objectReceipt'->'derivative'->'sha256','transformDigest',design_dependency_authority.digest(c->'response'->'descriptor'->'requestedTransform'),'verifier',t.verifier,'policyVersion',t.policy_version);
 checks:=r->'checks';
 IF (NOT design_managed_image.exact(r,ARRAY['schemaVersion','state','verificationBinding','checks','evidence','submissionAuthorized','adoptionAuthorized','publicEligible']) OR r->>'schemaVersion'<>'design-managed-image-verification-report-v1' OR r->'verificationBinding' IS DISTINCT FROM b OR r->'submissionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'adoptionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'publicEligible' IS DISTINCT FROM 'false'::jsonb OR NOT design_managed_image.exact(checks,ARRAY['sourceBinding','fullDecode','metadataRemoval','orientation','color','geometry']) OR NOT design_managed_image.strings(checks,ARRAY['sourceBinding','fullDecode','metadataRemoval','orientation','color','geometry']) OR EXISTS(SELECT 1 FROM jsonb_each_text(checks) WHERE value NOT IN ('unknown','failed','verified'))) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_REPORT_INVALID' USING ERRCODE='42501';END IF;
 SELECT bool_and(value='verified'),bool_or(value='failed') INTO allgood,anybad FROM jsonb_each_text(checks);
 IF (r->>'state' IS DISTINCT FROM CASE WHEN allgood THEN 'evidence_complete' WHEN anybad THEN 'validation_failed' ELSE 'pending_validation' END) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_REPORT_INVALID' USING ERRCODE='42501';END IF;
 ev:=r->'evidence';IF allgood THEN
 expected:=jsonb_build_object('schemaVersion','design-managed-image-evidence-v1','id','verification-'||design_dependency_authority.digest(jsonb_build_object('binding',b,'checks',checks)),'sourceRecordDigest',b->'sourceRecordDigest','responseDigest',b->'responseDigest','transformDigest',b->'transformDigest','verifiedSourceSha256',b->'sourceSha256','verifiedDerivativeSha256',b->'derivativeSha256','verifier',t.verifier,'checks',checks);
 IF (ev IS DISTINCT FROM expected OR jsonb_typeof(ev->'id') IS DISTINCT FROM 'string' OR ev->>'id'!~'^[A-Za-z0-9_-]{1,100}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_REPORT_INVALID' USING ERRCODE='42501';END IF;
 ELSE IF (ev IS DISTINCT FROM 'null'::jsonb) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_REPORT_INVALID' USING ERRCODE='42501';END IF;END IF;
 PERFORM design_managed_derived.task_context(a,id);RETURN c||jsonb_build_object('verificationReport',r);END$$;
CREATE FUNCTION design_managed_derived.publish_report(token text,scope jsonb,id text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;old jsonb;BEGIN
 IF (session_user<>'design_derived_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_derived.issuer_auth(token,scope);PERFORM design_managed_derived.check_report(a,id,r);SELECT report INTO old FROM design_managed_derived.reports WHERE task_id=id;IF FOUND THEN IF (NOT EXISTS(SELECT 1 FROM design_managed_derived.reports WHERE task_id=id AND active) OR old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_CONFLICT';END IF;ELSE INSERT INTO design_managed_derived.reports VALUES(id,r,true);END IF;RETURN design_managed_derived.check_report(design_managed_derived.issuer_auth(token,scope),id,r);END$$;
CREATE FUNCTION design_managed_derived.read_verification_status(id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT report INTO STRICT r FROM design_managed_derived.reports WHERE task_id=id AND active;RETURN design_managed_derived.check_report(a,id,r);END$$;
CREATE FUNCTION design_managed_derived.read_verified(id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT report INTO STRICT r FROM design_managed_derived.reports WHERE task_id=id AND active;IF (r->>'state' IS DISTINCT FROM 'evidence_complete') IS DISTINCT FROM false THEN RAISE EXCEPTION 'DERIVED_NOT_VERIFIED' USING ERRCODE='42501';END IF;RETURN design_managed_derived.check_report(a,id,r);END$$;
CREATE FUNCTION design_managed_derived.revoke(kind text,id text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n int;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));
 IF kind='permission' AND session_user='design_derived_storage_issuer' THEN UPDATE design_managed_derived.permissions SET active=false WHERE permissions.id=revoke.id AND active;
 ELSIF kind='task' AND session_user='design_derived_verifier_authorizer' THEN UPDATE design_managed_derived.tasks SET active=false WHERE tasks.id=revoke.id AND active;
 ELSIF kind='report' AND session_user='design_derived_verifier' THEN UPDATE design_managed_derived.reports SET active=false WHERE task_id=revoke.id AND active;
 ELSE RAISE EXCEPTION 'DERIVED_DENIED' USING ERRCODE='42501';END IF;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='design_managed_derived' LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_managed_image_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_identity_runtime,design_derived_storage_issuer,design_derived_verifier_authorizer,design_derived_verifier',f.sig);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION design_managed_derived.claim_put(jsonb),design_managed_derived.guard_put(jsonb),design_managed_derived.publish_object(text,jsonb),design_managed_derived.read_object(text),design_managed_derived.read_verified(text),design_managed_derived.read_verification_status(text) TO design_identity_runtime;
GRANT EXECUTE ON FUNCTION design_managed_derived.issue_put(text,jsonb,text,jsonb,bigint) TO design_derived_storage_issuer;
GRANT EXECUTE ON FUNCTION design_managed_derived.issue_task(text,jsonb,text,text,jsonb,text,bigint) TO design_derived_verifier_authorizer;
GRANT EXECUTE ON FUNCTION design_managed_derived.publish_report(text,jsonb,text,jsonb),design_managed_derived.read_task(text,jsonb,text),design_managed_derived.guard_task(text,jsonb,text,jsonb) TO design_derived_verifier;
GRANT EXECUTE ON FUNCTION design_managed_derived.revoke(text,text) TO design_derived_storage_issuer,design_derived_verifier_authorizer,design_derived_verifier;
REVOKE CREATE ON SCHEMA design_managed_derived FROM design_managed_image_capability;
REVOKE ALL ON ALL TABLES IN SCHEMA design_managed_derived FROM PUBLIC,anon,authenticated,design_identity_runtime,design_derived_storage_issuer,design_derived_verifier_authorizer,design_derived_verifier;
